import{_ as a,Y as t,o as r,c as i,aq as l,H as s}from"./chunks/framework.CZHj4g6B.js";import"./chunks/theme.BZcG_oVy.js";const n="/YukiHookAPI/images/yukihookapi-projectbuilder-zh-cn.png",_=JSON.parse('{"title":"YukiHookAPI 构建工具","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/tools/yukihookapi-projectbuilder.md","filePath":"zh-cn/tools/yukihookapi-projectbuilder.md"}'),p={name:"zh-cn/tools/yukihookapi-projectbuilder.md"};function c(u,o,h,d,k,g){const e=t("NolebaseGitChangelog");return r(),i("div",null,[o[0]||(o[0]=l('<h1 id="yukihookapi-project-builder" tabindex="-1">YukiHookAPI 构建工具 <a class="header-anchor" href="#yukihookapi-project-builder" aria-label="Permalink to &quot;YukiHookAPI 构建工具&quot;">​</a></h1><blockquote><p>这是一个使用 <code>YukiHookAPI</code> 作为核心的 Xposed 模块自动构建工具。</p><p>实现自动化搜索依赖快速搭建一个包含 Xposed 模块环境的 Android 项目模板。</p></blockquote><img src="'+n+'" width="720"><h2 id="get-project" tabindex="-1">获取项目 <a class="header-anchor" href="#get-project" aria-label="Permalink to &quot;获取项目&quot;">​</a></h2><p>本项目完全开源免费，且会根据大家的使用情况持续维护，初代版本可能存在不完善或 BUG，欢迎反馈。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>项目构建器将会在 YukiHookAPI 发布第一个 <code>2.0.0</code> 版本之前做最后的维护，在新的版本发布后，这个项目将正式弃用。</p></div><p>项目地址 <a href="https://github.com/HighCapable/YukiHookAPI-ProjectBuilder" target="_blank" rel="noreferrer">YukiHookAPI-ProjectBuilder</a>。</p><p>若你想直接下载可以 <a href="https://github.com/HighCapable/YukiHookAPI-ProjectBuilder/releases" target="_blank" rel="noreferrer">点击这里</a> 前往 Release 发布地址。</p><h2 id="usage" tabindex="-1">使用方法 <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><blockquote><p>这里包含了基本的使用方法和功能讲解。</p></blockquote><h3 id="basic-usage" tabindex="-1">基本用法 <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;基本用法&quot;">​</a></h3><ul><li><p>软件使用过程需要当前设备已连接互联网，若项目依赖无法搜索请尝试 <strong>科学上网</strong> 。</p></li><li><p>启动软件后，对你期望创建的项目进行简单配置，点击右下角的 <strong>按钮</strong> 或菜单栏选择 <strong>项目 &gt; 开始创建</strong> 即可开始任务。</p></li><li><p>等待依赖自动搜索完成后，你可以对项目依赖进行配置，建议使用最新依赖保证项目的稳定性，构建工具也仅对最新依赖进行支持。</p></li><li><p>选择你需要创建项目的目录，开始后项目会在你选择的位置中创建，并等待整个过程完成，项目就创建好了。</p></li></ul><h3 id="config-template" tabindex="-1">配置模板 <a class="header-anchor" href="#config-template" aria-label="Permalink to &quot;配置模板&quot;">​</a></h3><p>配置模板是一个扩展功能，你可以选择菜单栏 <strong>项目 &gt; 配置模板 &gt; 新建模板</strong>，即可使用当前填写的配置创建一份模板，下次可以从 <strong>已保存的模板</strong> 中重新载入模板，即可还原当前配置。</p><h3 id="multilingual-support" tabindex="-1">多语言支持 <a class="header-anchor" href="#multilingual-support" aria-label="Permalink to &quot;多语言支持&quot;">​</a></h3><p>软件语言跟随当前系统，你可以在菜单栏 <strong>语言 (Language)</strong> 一栏手动选择软件的界面语言。</p>',16)),s(e)])}const P=a(p,[["render",c]]);export{_ as __pageData,P as default};
